// ===== O2 alarm settings – change these to your required values =====
const ALARM_LEVEL   = 19.5;            // % O2: alarm when BELOW this
const RECOVER_LEVEL = 20.0;            // % O2: clear alarm when back ABOVE this
const REMINDER_MS   = 15 * 60 * 1000;  // repeat email every 15 min while low
// =====================================================================

const o2 = Number(msg.payload && msg.payload.o2);
if (!Number.isFinite(o2)) {
    node.warn("Message without a valid o2 value: " + JSON.stringify(msg.payload));
    return null;
}

const device = (msg.topic || "").split("/")[1] || "unknown";

// ----- GPS location (optional fields lat / lon / acc in the payload) -----
// The board may send location less often than O2, so remember the last fix.
const lat = Number(msg.payload.lat), lon = Number(msg.payload.lon);
if (Number.isFinite(lat) && Number.isFinite(lon) && !(lat === 0 && lon === 0)) {
    flow.set("loc_" + device, {
        lat, lon,
        acc: Number(msg.payload.acc) || null,
        time: new Date().toLocaleString("en-ZA", { timeZone: "Africa/Johannesburg" })
    });
}
const loc = flow.get("loc_" + device);
const locText = loc
    ? `\nLocation: ${loc.lat.toFixed(5)}, ${loc.lon.toFixed(5)}` +
      (loc.acc ? ` (±${Math.round(loc.acc)} m)` : "") + ` – fix at ${loc.time}` +
      `\nMap: https://www.google.com/maps?q=${loc.lat},${loc.lon}`
    : "\nLocation: no GPS fix yet";
const now = Date.now();
const when = new Date().toLocaleString("en-ZA", { timeZone: "Africa/Johannesburg" });
let inAlarm = context.get("inAlarm") || false;
let lastNotify = context.get("lastNotify") || 0;
let email = null;

if (!inAlarm && o2 < ALARM_LEVEL) {
    inAlarm = true;
    lastNotify = now;
    email = {
        topic: `ALARM: Low O2 ${o2.toFixed(1)} % on ${device}`,
        payload: `Oxygen level dropped to ${o2.toFixed(2)} % at ${when}.\n` +
                 `Alarm level: ${ALARM_LEVEL} %.` + locText
    };
} else if (inAlarm && o2 >= RECOVER_LEVEL) {
    inAlarm = false;
    email = {
        topic: `Recovered: O2 back to ${o2.toFixed(1)} % on ${device}`,
        payload: `Oxygen level recovered to ${o2.toFixed(2)} % at ${when}.` + locText
    };
} else if (inAlarm && now - lastNotify > REMINDER_MS) {
    lastNotify = now;
    email = {
        topic: `REMINDER: O2 still low (${o2.toFixed(1)} %) on ${device}`,
        payload: `Oxygen level is still ${o2.toFixed(2)} % at ${when}.` + locText
    };
}

context.set("inAlarm", inAlarm);
context.set("lastNotify", lastNotify);

node.status({ fill: inAlarm ? "red" : "green", shape: "dot", text: o2.toFixed(1) + " %" });

const value  = { payload: o2, topic: "O2", alarm: inAlarm };  // alarm flag colours the value red
const calNote = msg.payload.cal === false ? " · NOT CALIBRATED"
              : (msg.payload.cal_due ? " · calibration due" : "");
const status = { payload: (inAlarm ? `LOW O2 ALARM (${o2.toFixed(1)} %)` : `OK (${o2.toFixed(1)} %)`) + calNote };

// Map marker (only once we have a location)
const marker = loc ? { payload: {
    name: device,
    lat: loc.lat, lon: loc.lon,
    accuracy: loc.acc || undefined,
    icon: "fa-tint", iconColor: inAlarm ? "red" : "green",
    label: `${device}: ${o2.toFixed(1)} % O2`,
    O2: o2.toFixed(2) + " %",
    status: inAlarm ? "LOW O2 ALARM" : "OK",
    last_fix: loc.time
} } : null;

// Remember the marker (to redraw it when a browser opens the map) and
// centre the map on it
if (marker) flow.set("last_marker", marker.payload);
const mapMsgs = marker
    ? [marker, { payload: { command: { lat: loc.lat, lon: loc.lon, zoom: 16 } } }]
    : null;

// outputs: 1 = value display/chart, 2 = email, 3 = status text, 4 = map
return [value, email, status, mapMsgs];

const when = new Date().toLocaleString("en-ZA", { timeZone: "Africa/Johannesburg" });
msg.topic = "WARNING: O2 sensor offline";
msg.payload = `No data received from the Thingy:91 X for 10 minutes (checked at ${when}).\n` +
              `Check power, LTE coverage and the board.`;
return msg;

// Combines calibration info, command results and live readings for the panel
const p = msg.payload || {};
const parts = (msg.topic || "").split("/");
const dev = parts[1];
if (dev) flow.set("cal_device", dev);

let s = flow.get("cal_panel_" + dev) || {};
const tz = { timeZone: "Africa/Johannesburg" };
const fmt = t => (t > 0 ? new Date(t * 1000).toLocaleString("en-ZA", tz) : "date unknown");

if (parts[2] === "status") {
    if (p.type === "cal_info") {
        s.info = {
            due: p.due,
            interval: p.interval_d,
            span: p.has_span
                ? `${(p.span_uv / 1000).toFixed(3)} mV = ${p.span_pct.toFixed(2)} % O2`
                : `not calibrated (datasheet ${(p.span_uv / 1000).toFixed(3)} mV in air)`,
            span_date: p.has_span ? fmt(p.span_time) : "never",
            age: p.has_span && p.age_d >= 0 ? `${p.age_d} days` : "",
            zero: p.has_zero ? `${(p.zero_uv / 1000).toFixed(3)} mV (calibrated)`
                             : `${(p.zero_uv / 1000).toFixed(3)} mV (datasheet)`,
            zero_date: p.has_zero ? fmt(p.zero_time) : "",
            health: p.health >= 0 ? p.health : null,
            health_warn: p.health_warn,
            comp: (p.p_comp ? (p.p_cal > 0 ? `pressure (reference ${p.p_cal.toFixed(1)} kPa)`
                                            : "pressure: no reference yet")
                            : "pressure off")
                  + (p.t_coeff_ppm ? `, temperature ${(p.t_coeff_ppm / 10000).toFixed(2)} %/°C` : "")
        };
    } else if (p.type === "cal_result") {
        s.busy = p.ok && /started/i.test(p.msg || "");
        s.result = {
            ok: p.ok,
            msg: p.msg,
            time: new Date().toLocaleTimeString("en-ZA", tz)
        };
    }
} else if (typeof p.mv === "number") {
    s.live = { mv: p.mv, p: p.p, t: p.t };
}

flow.set("cal_panel_" + dev, s);
msg.payload = s;
return msg;

// Send the panel's command to the board, and show "waiting" in the panel
const dev = flow.get("cal_device") || "thingy91x";
const tz = { timeZone: "Africa/Johannesburg" };
const out = { topic: `sensors/${dev}/cmd`, payload: msg.payload };

let s = flow.get("cal_panel_" + dev) || {};
s.result = {
    ok: true,
    msg: `Command "${msg.payload.cmd}" sent - waiting for the board to answer...`,
    time: new Date().toLocaleTimeString("en-ZA", tz)
};
flow.set("cal_panel_" + dev, s);

return [out, { payload: s }];

// ===== Air quality alarm levels – keep in sync with the firmware (Kconfig) =====
const CO2_ALARM  = 1400, CO2_CLEAR  = 1200;  // ppm CO2-equivalent
const TVOC_ALARM = 450,  TVOC_CLEAR = 350;   // ppb TVOC-equivalent
const REMINDER_MS = 15 * 60 * 1000;          // repeat email every 15 min while high
// ================================================================================

const p = msg.payload || {};
const device = (msg.topic || "").split("/")[1] || "unknown";
const tz = { timeZone: "Africa/Johannesburg" };
const when = new Date().toLocaleString("en-ZA", tz);

// ----- GPS location (shared with the O2 flow) -----
const lat = Number(p.lat), lon = Number(p.lon);
if (Number.isFinite(lat) && Number.isFinite(lon) && !(lat === 0 && lon === 0)) {
    flow.set("loc_" + device, { lat, lon, acc: Number(p.acc) || null, time: when,
        src: ({ manual: "Manual", wifi: "Wi-Fi", gnss: "GPS", cell: "Cell towers" })[p.loc] || "GPS" });
}
const loc = flow.get("loc_" + device);
const locText = loc
    ? `\nLocation: ${loc.lat.toFixed(5)}, ${loc.lon.toFixed(5)}\nMap: https://www.google.com/maps?q=${loc.lat},${loc.lon}`
    : "\nLocation: no GPS fix yet";

// ----- Sensor not delivering valid data yet -----
if (p.status !== "ok") {
    const text = {
        warmup: "Warming up – first valid reading about 5 min after power-on",
        busy:   "Sensor busy – waiting for the next reading",
        error:  "SENSOR ERROR – the iAQ-Core reports constant errors (check or replace)",
        no_sensor: "SENSOR NOT DETECTED – board is online, but the iAQ-Core does not answer on I2C"
    }[p.status] || ("Sensor status: " + p.status);
    node.status({ fill: p.status === "error" ? "red" : "blue", shape: "ring", text: p.status });

    const marker = loc ? { payload: {
        name: device, lat: loc.lat, lon: loc.lon, accuracy: loc.acc || undefined,
        icon: "fa-exclamation-triangle", iconColor: "orange",
        label: `${device}: SENSOR NOT DETECTED`,
        status: "SENSOR NOT DETECTED", location: loc.src || "GPS", last_fix: loc.time
    } } : null;
    if (marker) flow.set("last_marker", marker.payload);
    const mapMsgs = marker
        ? [marker, { payload: { command: { lat: loc.lat, lon: loc.lon, zoom: 16 } } }]
        : null;

    return [null, null, null, { payload: text }, mapMsgs];
}

const co2 = Number(p.co2), tvoc = Number(p.tvoc);
let inAlarm = context.get("inAlarm") || false;
let lastNotify = context.get("lastNotify") || 0;
const now = Date.now();
let email = null;
const values = `CO2-eq ${co2} ppm (alarm ${CO2_ALARM}), TVOC-eq ${tvoc} ppb (alarm ${TVOC_ALARM})`;

if (!inAlarm && (co2 >= CO2_ALARM || tvoc >= TVOC_ALARM)) {
    inAlarm = true; lastNotify = now;
    email = { topic: `ALARM: Poor air quality on ${device}`, payload: `${values} at ${when}.` + locText };
} else if (inAlarm && co2 < CO2_CLEAR && tvoc < TVOC_CLEAR) {
    inAlarm = false;
    email = { topic: `Recovered: Air quality normal on ${device}`, payload: `${values} at ${when}.` + locText };
} else if (inAlarm && now - lastNotify > REMINDER_MS) {
    lastNotify = now;
    email = { topic: `REMINDER: Air quality still poor on ${device}`, payload: `${values} at ${when}.` + locText };
}
context.set("inAlarm", inAlarm);
context.set("lastNotify", lastNotify);

// Each value turns red on its own when it is the one causing the alarm
const co2High  = co2  >= CO2_ALARM  || (inAlarm && co2  >= CO2_CLEAR);
const tvocHigh = tvoc >= TVOC_ALARM || (inAlarm && tvoc >= TVOC_CLEAR);

node.status({ fill: inAlarm ? "red" : "green", shape: "dot", text: `${co2} ppm / ${tvoc} ppb` });

const status = { payload: inAlarm ? `POOR AIR QUALITY (${co2} ppm, ${tvoc} ppb)`
                                  : `OK (${co2} ppm, ${tvoc} ppb)` };

const marker = loc ? { payload: {
    name: device, lat: loc.lat, lon: loc.lon, accuracy: loc.acc || undefined,
    icon: "fa-cloud", iconColor: inAlarm ? "red" : "green",
    label: `${device}: ${co2} ppm CO2-eq · ${tvoc} ppb TVOC`,
    CO2_eq: co2 + " ppm", TVOC_eq: tvoc + " ppb",
    status: inAlarm ? "POOR AIR QUALITY" : "OK", location: loc.src || "GPS", last_fix: loc.time
} } : null;

// Remember the marker (to redraw it when a browser opens the map) and
// centre the map on it
if (marker) flow.set("last_marker", marker.payload);
const mapMsgs = marker
    ? [marker, { payload: { command: { lat: loc.lat, lon: loc.lon, zoom: 16 } } }]
    : null;

// outputs: 1 = CO2 value/chart, 2 = TVOC value/chart, 3 = email, 4 = status, 5 = map
return [
    { payload: co2,  topic: "CO2-eq",  alarm: co2High },
    { payload: tvoc, topic: "TVOC-eq", alarm: tvocHigh },
    email, status, mapMsgs
];

const when = new Date().toLocaleString("en-ZA", { timeZone: "Africa/Johannesburg" });
msg.topic = "WARNING: Air quality sensor offline";
msg.payload = `No air quality data from the Thingy:91 X for 10 minutes (checked at ${when}).\n` +
              `Check power, LTE coverage and the board.`;
return msg;

// A browser opened the map: redraw the last marker and centre on it
if (!msg.payload || msg.payload.action !== "connected") return null;
const m = flow.get("last_marker");
if (!m) return null;
return [[
    { payload: m, _sessionid: msg._sessionid },
    { payload: { command: { lat: m.lat, lon: m.lon, zoom: 16 } }, _sessionid: msg._sessionid }
]];
